import unittest
from candidate import fruit_distribution

class TestFruitDistribution(unittest.TestCase):
    def test_fruit_distribution_normal_case(self):
        self.assertEqual(fruit_distribution("5 apples and 6 oranges", 19), 8)

    def test_fruit_distribution_zero_fruits(self):
        self.assertEqual(fruit_distribution("0 apples and 0 oranges", 10), 10)

    def test_fruit_distribution_large_number_fruits(self):
        self.assertEqual(fruit_distribution("100 apples and 50 oranges", 200), 50)

    def test_fruit_distribution_single_fruit_type(self):
        self.assertEqual(fruit_distribution("5 apples and 0 oranges", 10), 5)

    def test_fruit_distribution_no_fruits(self):
        self.assertEqual(fruit_distribution("", 10), 10)

    def test_fruit_distribution_invalid_input_string(self):
        with self.assertRaises(ValueError):
            fruit_distribution("5 apples and oranges", 10)

    def test_fruit_distribution_invalid_input_total_fruits(self):
        with self.assertRaises(TypeError):
            fruit_distribution("5 apples and 6 oranges", "ten")

    def test_fruit_distribution_negative_total_fruits(self):
        with self.assertRaises(ValueError):
            fruit_distribution("5 apples and 6 oranges", -10)

    def test_fruit_distribution_total_fruits_is_zero(self):
        self.assertEqual(fruit_distribution("5 apples and 6 oranges", 0), 0)

if __name__ == '__main__':
    unittest.main()
